package spec

import (
	"encoding/json"
	"math"
	"os"
	"strings"
	"testing"
)

// testdata/difflib.json was generated by CPython 3.14's difflib; the port
// must agree exactly.
func TestDifflibParity(t *testing.T) {
	raw, err := os.ReadFile("testdata/difflib.json")
	if err != nil {
		t.Fatal(err)
	}
	var v struct {
		Ratios []struct {
			A, B  string
			Ratio float64
		}
		Diffs []struct {
			A, B, Out string
			N         int
		}
	}
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	for _, r := range v.Ratios {
		if got := Similarity(r.A, r.B); math.Abs(got-r.Ratio) > 1e-12 {
			t.Errorf("Similarity(%.30q, %.30q) = %v want %v", r.A, r.B, got, r.Ratio)
		}
	}
	for _, d := range v.Diffs {
		if got := UnifiedDiff(d.A, d.B, "a", "b", d.N); got != d.Out {
			t.Errorf("UnifiedDiff n=%d\n got %q\nwant %q", d.N, got, d.Out)
		}
	}
}

func TestNormalizeBody(t *testing.T) {
	if got := NormalizeBody("\n\na  \n\n\n\tb\t\n\n"); got != "a\n\n\tb" {
		t.Errorf("%q", got)
	}
}

func reconcile(t *testing.T, before, after string) (*Doc, *Report) {
	t.Helper()
	next := mustParse(t, after)
	return next, Reconcile(PriorsOf(mustParse(t, before)), next)
}

func tierOf(t *testing.T, d *Doc, r *Report, slug string) Match {
	t.Helper()
	return r.Matches[bySlug(t, d, slug).Ordinal]
}

const rotationBody = "Refresh tokens rotate on every use. The previous token stays valid for a grace\nwindow of 60s to absorb in-flight requests.\n"

func TestReconcileUnchanged(t *testing.T) {
	src, _ := os.ReadFile("testdata/example-spec.md")
	d, r := reconcile(t, string(src), string(src))
	for _, m := range r.Matches {
		want := TierPath
		if d.Sections[m.Ordinal].PinKey != "" {
			want = TierPinned
		}
		if m.Tier != want || m.Prior != m.Ordinal {
			t.Errorf("%s: %+v", d.Sections[m.Ordinal].PathSlug, m)
		}
	}
	if len(r.Renamed)+len(r.Moved)+len(r.New)+len(r.Orphaned)+len(r.Removed)+len(r.PinDropped) != 0 {
		t.Errorf("report not empty: %+v", r)
	}
}

func TestReconcileRenameWithPin(t *testing.T) {
	before := "## Tokens\n\n<!-- agtrack:id grace-policy -->\n### Rotation\n\n" + rotationBody
	after := "## Token handling\n\n<!-- agtrack:id grace-policy -->\n### Rotating refresh tokens\n\nCompletely rewritten text.\n"
	d, r := reconcile(t, before, after)
	m := tierOf(t, d, r, "token_handling__rotating_refresh_tokens")
	if m.Tier != TierPinned || m.PriorKey != "grace-policy" || m.Confidence != 1 {
		t.Errorf("pinned rename: %+v", m)
	}
	if len(r.Renamed) != 1 {
		t.Fatalf("renamed %+v", r.Renamed)
	}
	var found bool
	for _, l := range r.Renamed {
		if l.Key == "grace-policy" && l.PriorPathSlug == "tokens__rotation" && l.PathSlug == "token_handling__rotating_refresh_tokens" {
			found = true
		}
	}
	if !found || len(r.Orphaned) != 0 {
		t.Errorf("report %+v", r)
	}
}

func TestReconcileRenameWithoutPin(t *testing.T) {
	before := "## Tokens\n\nToken lifetimes are global.\n\n### Rotation\n\n" + rotationBody + "\n### Revocation\n\nRevoking a refresh token revokes its entire family.\n"
	after := "## Tokens\n\nToken lifetimes are global.\n\n### Rotating refresh tokens\n\n" + strings.Replace(rotationBody, "every use", "each use", 1) + "\n### Revocation\n\nRevoking a refresh token revokes its entire family.\n"
	d, r := reconcile(t, before, after)
	m := tierOf(t, d, r, "tokens__rotating_refresh_tokens")
	if m.Tier != TierSimilar || m.Confidence < 0.9 || m.Confidence >= 1 {
		t.Fatalf("similar: %+v", m)
	}
	if len(r.Renamed) != 1 || r.Renamed[0].PriorHeading != "Rotation" || r.Renamed[0].Heading != "Rotating refresh tokens" || r.Renamed[0].Confidence != m.Confidence {
		t.Errorf("renamed %+v", r.Renamed)
	}
	if len(r.New)+len(r.Removed)+len(r.Orphaned) != 0 {
		t.Errorf("report %+v", r)
	}
}

func TestReconcileMove(t *testing.T) {
	before := "## Sessions\n\n### Idle timeout\n\nSessions idle for 14 days are closed.\n\n## Devices\n\nx\n"
	after := "## Sessions\n\n## Devices\n\nx\n\n### Idle timeout\n\nSessions idle for 7 days are closed.\n"
	d, r := reconcile(t, before, after)
	if m := tierOf(t, d, r, "devices__idle_timeout"); m.Tier != TierSlug {
		t.Fatalf("move: %+v", m)
	}
	if len(r.Moved) != 1 || r.Moved[0].PriorPathSlug != "sessions__idle_timeout" || r.Moved[0].PriorNumber != "1.1" || r.Moved[0].Number != "2.1" {
		t.Errorf("moved %+v", r.Moved)
	}
}

func TestReconcileAmbiguousSlugFallsThrough(t *testing.T) {
	// Two new `revocation` sections: tier 3 must not guess between them.
	before := "## Old\n\n### Revocation\n\nRevoking a refresh token revokes its entire family.\n"
	after := "## Tokens\n\n### Revocation\n\nRevoking a refresh token revokes its entire family.\n\n## Sessions\n\n### Revocation\n\nSomething unrelated about sessions entirely.\n"
	d, r := reconcile(t, before, after)
	if m := tierOf(t, d, r, "tokens__revocation"); m.Tier != TierSimilar {
		t.Errorf("tokens__revocation %+v", m)
	}
	if m := tierOf(t, d, r, "sessions__revocation"); m.Tier != TierNew {
		t.Errorf("sessions__revocation %+v", m)
	}
}

func TestReconcileSplitAndMergeNeverDetected(t *testing.T) {
	half1 := "Refresh tokens rotate on every use and the old one is kept for a grace window."
	half2 := "Revocation of one token revokes the whole family descended from a login."
	pinned := "<!-- agtrack:id tok -->\n## Tokens\n\n" + half1 + "\n\n" + half2 + "\n"
	split := "## Rotation\n\n" + half1 + "\n\n## Revocation\n\n" + half2 + "\n"
	d, r := reconcile(t, pinned, split)
	for _, s := range []string{"rotation", "revocation"} {
		if m := tierOf(t, d, r, s); m.Tier != TierNew {
			t.Errorf("split half %s matched %+v", s, m)
		}
	}
	if len(r.Orphaned) != 1 || r.Orphaned[0].Key != "tok" {
		t.Errorf("pinned parent must orphan: %+v", r.Orphaned)
	}

	merged := "## Tokens\n\n" + half1 + "\n\n" + half2 + "\n"
	d, r = reconcile(t, split, merged)
	if m := tierOf(t, d, r, "tokens"); m.Tier != TierNew {
		t.Errorf("merge matched %+v", m)
	}
	if len(r.Removed) != 2 {
		t.Errorf("removed %+v", r.Removed)
	}
}

func TestReconcilePinDropped(t *testing.T) {
	before := "<!-- agtrack:id keep -->\n## A\n\nbody\n"
	after := "## A\n\nbody\n"
	_, r := reconcile(t, before, after)
	if len(r.PinDropped) != 1 || r.PinDropped[0].Key != "keep" || r.PinDropped[0].Tier != TierPath {
		t.Errorf("pin dropped %+v", r.PinDropped)
	}
}

func TestReconcileRunnerUpMargin(t *testing.T) {
	// Two near-identical candidates: the best does not beat the runner-up
	// by 0.15, so nothing matches.
	body := "Sessions idle for fourteen days are closed by a nightly job run at midnight.\n"
	before := "## A\n\n" + body + "\n## B\n\n" + strings.Replace(body, "fourteen", "fifteen", 1)
	after := "## C\n\n" + strings.Replace(body, "fourteen", "sixteen", 1)
	d, r := reconcile(t, before, after)
	if m := tierOf(t, d, r, "c"); m.Tier != TierNew {
		t.Errorf("runner-up margin ignored: %+v", m)
	}
	// Empty container headings never match by similarity.
	d, r = reconcile(t, "## A\n", "## B\n")
	if m := tierOf(t, d, r, "b"); m.Tier != TierNew {
		t.Errorf("empty bodies matched: %+v", m)
	}
}

func TestReconcileBlocksAndDuplicatePins(t *testing.T) {
	before := "## A\n\n<!-- agtrack:block tbl -->\n\n| x |\n|---|\n"
	after := "## Renamed\n\nintro\n\n<!-- agtrack:block tbl -->\n\n| x |\n|---|\n| y |\n"
	d, r := reconcile(t, before, after)
	if m := tierOf(t, d, r, "renamed__tbl"); m.Tier != TierPinned {
		t.Errorf("block by key %+v", m)
	}
	if _, err := Parse([]byte(after + "\n<!-- agtrack:block tbl -->\n")); err == nil {
		t.Error("duplicate block key accepted")
	}
}
